def parse_expression(expr, bindings):
    try:
        # Parse the expression safely
        node = ast.parse(expr, mode='eval')
        if len(node.body) != 1:
            raise SyntaxError("Invalid expression")
        body = node.body

        # Evaluate the expression with bindings
        def evaluate(node, bindings):
            if isinstance(node, ast.Constant):
                return node.value
            elif isinstance(node, ast.Name):
                name = node.id
                if name in bindings:
                    return bindings[name]
                else:
                    raise NameError(f"Undefined variable: {name}")
            elif isinstance(node, ast.BinOp):
                left = evaluate(node.left, bindings)
                right = evaluate(node.right, bindings)
                if isinstance(node.op, ast.Add):
                    return left + right
                elif isinstance(node.op, ast.Sub):
                    return left - right
                elif isinstance(node.op, ast.Mult):
                    return left * right
                else:
                    raise SyntaxError(f"Unsupported operator: {type(node.op)}")
            else:
                raise SyntaxError(f"Unsupported node type: {type(node)}")

        return evaluate(body, bindings)
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

