            results[job_id] = -1

    def worker():
        nonlocal running_count
        while True:
            try:
                job_id, command = job_queue.get(timeout=1)
                if job_id is None:
                    break
                with lock:
                    running_count += 1
                run_job(job_id, command)
                with lock:
                    running_count -= 1
                job_queue.task_done()
            except queue.Empty:
                continue

    # Start worker processes
    for _ in range(max_parallel):
        thread = threading.Thread(target=worker)
        thread.daemon = True
        thread.start()

    # Add jobs to queue
    for job in root.findall('job'):
        job_id = job.get('id')
        command = job.find('command').text
        if job_id and command:
            job_queue.put((job_id, command))

    # Wait for all jobs to complete
    job_queue.join()

    print(json.dumps(results))

