def evaluate_expression(expr):
    try:
        # Replace {{...}} with evaluated expression
        # Remove outer quotes and evaluate
        expr = expr.strip()
        if expr.startswith('0') and len(expr) == 1:
            return 0
        # Remove outer quotes if present
        expr = expr.strip()
        # Remove any leading/trailing whitespace
        expr = expr.strip()
        # Evaluate the expression safely
        return int(eval(expr))
    except:
        raise ValueError(f"Invalid expression: {expr}")

def parse_query(query):
    # Replace {{...}} with evaluated expressions
    def replace_match(match):
        expr = match.group(1)
        try:
            # Evaluate the expression
            result = evaluate_expression(expr)
            return str(result)
        except Exception as e:
            raise ValueError(f"Error evaluating expression {expr}: {e}")

    # Find all {{...}} patterns
    pattern = r'\{\{([^}]+)\}\}'
    result = re.sub(pattern, replace_match, query)
    return result

def run_check(check):
    name = check["name"]
    db_path = check["db"]
    query = check["query"]
    threshold = check["threshold"]
    webhook = check["webhook"]

    # Parse and replace placeholders in query
    try:
        parsed_query = parse_query(query)
    except Exception as e:
        print(f"{name} {0} failed")
        return f"{name} {0} failed"

    # Connect to database and execute query
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(parsed_query)
        result = cursor.fetchone()
        if result is None:
            value = 0
        else:
            value = int(result[0])
        conn.close()
    except Exception as e:
        print(f"{name} {0} failed")
        return f"{name} {0} failed"

    # Determine outcome
    if value > threshold:
        try:
            response = requests.post(
                webhook,
                json={"check": name, "value": value},
                headers={"Content-Type": "application/json"}
            )
            if response.status_code < 400:
                outcome = "sent"
            else:
                outcome = "failed"
        except Exception:
            outcome = "failed"
    else:
        outcome = "skipped"

    return f"{name} {value} {outcome}"

