def parse_config(config_path):
    feed_url = None
    threshold = None

    with open(config_path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key == 'feed_url':
                    feed_url = value
                elif key == 'threshold':
                    threshold = value
    return feed_url, threshold

def extract_price_sum(xml_content):
    root = ET.fromstring(xml_content)
    prices = []
    for elem in root.iter():
        if elem.tag == 'price':
            try:
                price = float(elem.text)
                prices.append(price)
            except (ValueError, TypeError):
                continue
    return sum(prices)

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file_path>")
        sys.exit(1)

    config_path = sys.argv[1]
    feed_url, threshold_str = parse_config(config_path)

    if not feed_url:
