import sys
import requests
import re
import json

def evaluate_expression(expression, data):
    """Evaluate an arithmetic expression using the provided data dictionary."""
    try:
        # Replace each key in the expression with its corresponding value from data
        for key, value in data.items():
            expression = expression.replace(f"{{{{ {key} }}}}", str(value))
        # Evaluate the expression using eval
        return eval(expression)
    except Exception as e:
        return str(e)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report_renderer.py <url> <template_path>")
        sys.exit(1)

    url = sys.argv[1]
    template_path = sys.argv[2]

    try:
        # Fetch JSON data from URL
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()

        # Read template file
        with open(template_path, 'r', encoding='utf-8') as file:
            template = file.read()

        # Replace placeholders with evaluated expressions
        # Use regex to find all expressions in the format {{ expression }}
        placeholders = re.findall(r'\{\{([^}]+)\}\}', template)
        for placeholder in placeholders:
            try:
                result = evaluate_expression(placeholder, data)
                template = template.replace(f"{{{{ {placeholder} }}}}", str(result))
            except Exception as e:
                template = template.replace(f"{{{{ {placeholder} }}}}", str(e))

        # Output the completed HTML
        print(template)

    except requests.exceptions.RequestException as e:
        print(f"Error fetching URL: {e}", file=sys.stderr)
        sys.exit(1)
